def safe_div(a, b):
    try:
        return a / b
    except ZeroDivisionError:
        return None
    except (TypeError, ValueError) as e:
        print("ошибка:", e)
        return None

print(safe_div(6, 3), safe_div(1, 0))
print(safe_div("a", 2))

