def set_age(age):
    if age < 0:
        raise ValueError(f"возраст не может быть {age}")
    return age

try:
    set_age(-5)
except ValueError as e:
    print(e)

class InsufficientFunds(Exception):
    pass

def withdraw(balance, x):
    if x > balance:
        raise InsufficientFunds(f"нужно ещё {x - balance}")
    return balance - x

try:
    withdraw(100, 150)
except InsufficientFunds as e:
    print(e)

def load(cfg):
    try:
        return cfg["port"]
    except KeyError as e:
        raise RuntimeError("в настройках нет порта") from e

try:
    load({})
except RuntimeError as e:
    print(e, "| причина:", repr(e.__cause__))

def mean(xs):
    assert len(xs) > 0, "список не должен быть пустым"   # ошибка программиста
    return sum(xs) / len(xs)

def parse_age(text):
    age = int(text)
    if age < 0:
        raise ValueError("возраст < 0")                  # ошибка данных
    return age

print(mean([1, 2, 3]), parse_age("20"))
